  g.fillStyle = '#1a0b2a'; g.strokeStyle = '#c99bff'; g.lineWidth = 6;
  g.beginPath(); g.moveTo(16,80); g.quadraticCurveTo(128,-10,240,80); g.quadraticCurveTo(128,170,16,80); g.closePath(); g.fill(); g.stroke();
  const gr = g.createRadialGradient(128,80,4,128,80,46); gr.addColorStop(0,'#ffe0ff'); gr.addColorStop(0.4,'#a35cff'); gr.addColorStop(1,'#2a0f45');
  g.fillStyle = gr; g.beginPath(); g.arc(128,80,44,0,Math.PI*2); g.fill();
