    m.position.set(Math.cos(a)*0.31, 0.45 + Math.sin(a)*0.12, -0.05 + Math.sin(a)*0.3);
    m.rotation.set(k%2 ? Math.PI/2 : 0, -a, 0.3); m.castShadow = true; body.add(m); chainLinksArr.push(m);
