    const pillar = new THREE.Mesh(new THREE.CylinderGeometry(0.4, 0.48, 2.2, 28, 1, true), new THREE.MeshBasicMaterial({ map:pillarTex, color:0xbfe8ff, transparent:true, depthWrite:false, blending:ADD, side:THREE.DoubleSide, opacity:0 }));
    pillar.position.set(x, y + 1.1, z); scene.add(pillar);
    tween(1.0, t => { c.material.opacity = Math.sin(Math.PI*t); c.rotation.z = t*3; c.scale.setScalar(0.6 + 0.4*ease.out(t)); pillar.material.opacity = 0.8*Math.sin(Math.PI*t); })
