/* ---- UI テーマ: 石の質感テクスチャを生成して背景とパネルに使う ---- */
(function makeStoneTexture(){
  try{
    const c = document.createElement('canvas'); c.width = c.height = 384;
    const g = c.getContext('2d'), R = rng(77);
    g.fillStyle = '#808080'; g.fillRect(0,0,384,384);
    for(let k=0;k<2600;k++){ const x = R()*384, y = R()*384, r = 0.6 + R()*2.4; g.fillStyle = R()<0.5 ? `rgba(255,255,255,${0.04+R()*0.07})` : `rgba(0,0,0,${0.05+R()*0.1})`; g.beginPath(); g.arc(x,y,r,0,Math.PI*2); g.fill(); }
    g.lineCap = 'round';
    for(let k=0;k<5;k++){ let x = R()*384, y = R()*384, a = R()*Math.PI*2; g.beginPath(); g.moveTo(x,y); for(let j=0;j<9;j++){ a += (R()-.5)*1.0; x += Math.cos(a)*18; y += Math.sin(a)*18; g.lineTo(x,y); } g.strokeStyle = 'rgba(0,0,0,0.28)'; g.lineWidth = 1.6; g.stroke(); }
    document.documentElement.style.setProperty('--b3-tex', `url(${c.toDataURL('image/jpeg', 0.8)})`);
  }catch(e){}
})();
