  await uiTween(0.8, t => bubbles.forEach(o => { const k = Math.max(0, Math.min(1, (t - o.d)/0.6)); const q = bez(a, b, 90, ease.inOut(k)); o.m.position.copy(P(q.x + o.ox*Math.sin(Math.PI*k), q.y + o.oy*Math.sin(Math.PI*k), 40)); o.m.scale.setScalar(0.5 + Math.sin(Math.PI*k)); }));
  bubbles.forEach(o => uiDispose(o.m));
  const c = card3D(null, false, 1); c.position.copy(P(b.x, b.y, 60));
  uiSpark(b.x, b.y, 0xd8c8ff, 18);
  await uiTween(0.45, t => { c.scale.setScalar(Math.max(0.01, ease.back(t))); c.rotation.y = (1-t)*Math.PI; });
  await uiTween(0.25, t => { c.scale.setScalar(1 - t*0.3); c.children[0].material.forEach(m => { m.transparent = true; m.opacity = 1 - t; }); });
