/* ---------- 5: 手札を盗み取る大蛇 ---------- */
override('triggerGreenVortexSteal', orig => parallel(orig, (targetIdx, handIdx, receiverIdx) => uiFx(async () => {
  const a = casterPx(receiverIdx), b = panelPx(targetIdx, 'hand'), home = panelPx(receiverIdx, 'hand');
  const segs = [];
  const scaleM = new THREE.MeshLambertMaterial({ color:0xe6eaf0, emissive:0x2a2e36 }), bellyM = new THREE.MeshLambertMaterial({ color:0x3a6aa8, emissive:0x0a1a30 });
  for(let k=0;k<16;k++){ const m = new THREE.Mesh(new THREE.SphereGeometry(13 - k*0.45, 14, 10), k%3===0 ? bellyM : scaleM); ui.sc.add(m); segs.push(m); }
  const fang = new THREE.Mesh(new THREE.ConeGeometry(5, 16, 6), new THREE.MeshBasicMaterial({ color:0xfff6dc })); segs[0].add(fang); fang.position.set(0, -10, 6); fang.rotation.x = Math.PI;
  const eye = new THREE.Mesh(new THREE.SphereGeometry(3, 8, 6), new THREE.MeshBasicMaterial({ color:0x6ac8ff })); segs[0].add(eye); eye.position.set(5, 4, 10);
  const path = (t, from, to) => { const q = bez(from, to, 70, t); return { x:q.x + Math.sin(t*14)*10*(1-t), y:q.y }; };
  // 相手の手札へ伸びる
  await uiTween(0.5, t => segs.forEach((m,k) => { const tt = Math.max(0, ease.out(t) - k*0.035); const q = path(tt, a, b); m.position.copy(P(q.x, q.y, 50 - k)); }));
  uiSpark(b.x, b.y, 0x8fffb0, 14);
  const card = card3D(null, false, 0.9); card.position.copy(P(b.x, b.y, 70));
  // 咥えて持ち帰る
  await uiTween(0.6, t => {
    segs.forEach((m,k) => { const tt = Math.max(0, ease.inOut(t) - k*0.035); const q = path(tt, b, home); m.position.copy(P(q.x, q.y, 50 - k)); });
    card.position.copy(segs[0].position).add(new THREE.Vector3(0, -14, 20)); card.rotation.z = Math.sin(t*20)*0.15;
  });
  uiSpark(home.x, home.y, 0x8fffb0, 14);
  await uiTween(0.25, t => segs.forEach(m => m.scale.setScalar(1 - t)));
  segs.forEach(uiDispose); uiDispose(card);
})));

